<?php
function regenerate_brand_icons(string $url):void{
 // Only local administrator uploads are decoded; never fetch arbitrary remote URLs.
 if(!preg_match('#^/uploads/content/[a-f0-9]+\.(png|jpg|webp|gif)$#',$url))return;$root=__DIR__.'/../public';$path=$root.$url;$size=getimagesize($path);if(!$size||$size[0]*$size[1]>25000000)throw new RuntimeException('Brand image is too large');$img=imagecreatefromstring(file_get_contents($path));if(!$img)throw new RuntimeException('Unable to decode brand image');
 foreach([192,512,180] as $n){$canvas=imagecreatetruecolor($n,$n);imagealphablending($canvas,false);imagesavealpha($canvas,true);imagefill($canvas,0,0,imagecolorallocatealpha($canvas,0,0,0,127));$ratio=min($n/imagesx($img),$n/imagesy($img));$w=(int)(imagesx($img)*$ratio);$h=(int)(imagesy($img)*$ratio);imagecopyresampled($canvas,$img,(int)(($n-$w)/2),(int)(($n-$h)/2),0,0,$w,$h,imagesx($img),imagesy($img));$tmp=$root.'/app/icon-'.$n.'.tmp.png';imagepng($canvas,$tmp);rename($tmp,$root.'/app/icon-'.$n.'.png');imagedestroy($canvas);}imagedestroy($img);
 $q=db()->query("SELECT setting_value FROM site_settings WHERE setting_key='brand_name'");$name=$q->fetchColumn()?:'TDC TECH';$manifest=['id'=>'/app/','name'=>$name,'short_name'=>$name,'start_url'=>'/app/launch.php','scope'=>'/','display'=>'standalone','background_color'=>'#101116','theme_color'=>'#101116','icons'=>[['src'=>'/app/icon-192.png?v='.time(),'sizes'=>'192x192','type'=>'image/png','purpose'=>'any'],['src'=>'/app/icon-512.png?v='.time(),'sizes'=>'512x512','type'=>'image/png','purpose'=>'any']]];file_put_contents($root.'/app/manifest.webmanifest',json_encode($manifest,JSON_UNESCAPED_SLASHES));
}
